import java.util.Arrays;
class LoanReceipt {private final String memberId;private final String[] bookIds;public LoanReceipt(String id,String[] books){memberId=id;bookIds=Arrays.copyOf(books,books.length);}public String getMemberId(){return memberId;}public String[] getBookIds(){return Arrays.copyOf(bookIds,bookIds.length);}public LoanReceipt withCorrectedBookId(int i,String id){if(i<0||i>=bookIds.length)throw new IndexOutOfBoundsException("Invalid book index");String[] a=getBookIds();a[i]=id;return new LoanReceipt(memberId,a);}}
class ReferenceOnlyLoanReceipt extends LoanReceipt {private final String roomNumber;public ReferenceOnlyLoanReceipt(String id,String[] books,String room){super(id,books);roomNumber=room;}public String getRoomNumber(){return roomNumber;}}
public class CirculationLedger {private static String branchCode;static{branchCode="PT-LIB-01";}static String processNightlyCirculation(LoanReceipt[] a){int p=0,n=0,r=0,g=0;for(LoanReceipt x:a){if(x==null){n++;continue;}p++;if(x instanceof ReferenceOnlyLoanReceipt)r++;else g++;}return p+" processed | "+n+" null skipped | "+r+" reference-only | "+g+" regular";}
public static void main(String[] args){LoanReceipt r=new LoanReceipt("LIB-8841",new String[]{"BK-100","BK-101"});String[] ids=r.getBookIds();ids[0]="HACKED";System.out.println(r.getBookIds()[0]);LoanReceipt c=r.withCorrectedBookId(1,"BK-102");System.out.println(Arrays.toString(r.getBookIds()));System.out.println(Arrays.toString(c.getBookIds()));LoanReceipt[] a={new ReferenceOnlyLoanReceipt("LIB-001",new String[]{"BK-200"},"Reading Room 3"),null,new LoanReceipt("LIB-002",new String[]{"BK-201"})};System.out.println(processNightlyCirculation(a));}}
